def hook(ctx, nb):
    tt = text(getv(ctx, 'task.task_type', ''))
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(getv(ctx, 'world.inventory', ''))
    if target and act.startswith('take ') and target in act and 'pick up' in obs:
        nb['carrying_target'] = True
    if target and act.startswith('put ') and target in act and 'you put' in obs:
        nb['carrying_target'] = False
    if target and verb and target in act and act.startswith(verb + ' ') and 'nothing happens' not in obs:
        nb['transformed'] = True
    pc = getv(ctx, 'world.placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if target and act.startswith('put ') and target in act and 'you put' in obs and dest and dest in act:
        if pc < 1:
            pc = 1
    nb['placed_count'] = pc
    carrying = bool(target and target in inv and 'nothing' not in inv and 'not carrying' not in inv)
    wrong = bool(inv and target and target not in inv and 'nothing' not in inv and 'not carrying' not in inv)
    if wrong:
        stage = 'wrong_inventory'
    elif not target:
        stage = 'find_target'
    elif carrying:
        if verb and not nb.get('transformed'):
            stage = 'transform'
        else:
            stage = 'put_target'
    else:
        if pc > 0 and 'pick_two' in tt and pc < 2:
            stage = 'find_target'
        else:
            stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['required_verb'] = verb
    return None

