def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or 'target object'
    dest = nb.get('destination_type') or 'destination'
    verb = nb.get('required_verb') or needverb(nb.get('task_type', ''))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the requested ' + target + '. Do not place a different object; recover by setting it down if needed, then find the target type.'
    elif stage == 'transform' and verb:
        msg = 'You are carrying the ' + target + '. Before placing it, use the admissible ' + verb + ' action at the proper appliance or basin, then carry it to the ' + dest + '.'
    elif stage == 'put_target':
        msg = 'The ' + target + ' is ready. Use the admissible put action at the ' + dest + ' and do not take it back afterward.'
    elif stage == 'find_target' and 'pick_two' in (nb.get('task_type') or '') and nb.get('placed_count', 0) > 0:
        msg = 'One ' + target + ' is already placed. Leave it there, find another ' + target + ', and use the same ' + dest + ' destination.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

